<?php
use App\Application\Customers\PartyService;use App\Models\PartyIdentifier;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Crypt;use Illuminate\Validation\ValidationException;
uses(RefreshDatabase::class);
test('identity document is encrypted and duplicate registration is rejected',function(){$service=app(PartyService::class);$party=$service->create(['type'=>'PERSON','display_name'=>'Amina N.','phone_e164'=>'+237670000001','identifier_type'=>'NATIONAL_ID','identifier_value'=>'CM-1234-5678','identifier_country'=>'CM']);$id=PartyIdentifier::where('party_id',$party->id)->firstOrFail();expect($id->getRawOriginal('value_encrypted'))->not->toContain('12345678')->and(Crypt::decryptString($id->getRawOriginal('value_encrypted')))->toBe('CM12345678')->and($id->masked_value)->toEndWith('5678');expect(fn()=>$service->create(['type'=>'PERSON','display_name'=>'Duplicate','phone_e164'=>'+237670000002','identifier_type'=>'NATIONAL_ID','identifier_value'=>'CM 1234 5678','identifier_country'=>'CM']))->toThrow(ValidationException::class);});
